3|namespace Tests\Feature;
4|
5|use App\Enums\GradeType;
6|use App\Enums\Role;
7|use App\Models\Course;
8|use App\Models\CourseEnrollment;
9|use App\Models\Grade;
10|use App\Models\Setting;
11|use App\Models\Student;
12|use App\Models\User;
13|use App\Services\Transcript;
14|use Illuminate\Foundation\Testing\RefreshDatabase;
15|use Tests\TestCase;
16|
17|/*
18|||---------------------------------------------------------------------------
19||| کارنامهٔ رسمی (شماره 37، قاعدهٔ R4)
20|||
21||| سند رسمی است، پس سه چیز باید اثبات شود:
22|||   ۱. بدون layout پنل چاپ می‌شود — کارنامه‌ای که نیمه‌اش منو است سند نیست.
23|||   ۲. ریزنمرات، نمرهٔ نهایی و وضعیت قبولی روی کاغذ هستند و از همان
24|||      محاسبه‌ای می‌آیند که پنل استفاده می‌کند.
25|||   ۳. دانش‌آموزِ بدون نمره هم سند می‌گیرد، با وضعیت «فاقد سابقه» و بدون
26|||      خطا — نبودن نمره یعنی هنوز سنجیده نشده، نه اینکه صفر گرفته باشد.
27|||
28||| نمرهٔ قبولی از تنظیمات می‌آید و مقدار خراب نباید همه را مردود کند.
29|*/
30|
31|class TranscriptTest extends TestCase
32|{
33|    use RefreshDatabase;
34|
35|    private function actingAsRole(Role $role): User
36|    {
37|        $user = User::factory()->role($role)->create();
38|
39|        $this->actingAs($user);
40|
41|        return $user;
42|    }
43|
44|    /** دانش‌آموزِ ثبت‌نام‌قطعی‌شده در یک دوره. */
45|    private function enrolled(): array
46|    {
47|        $course = Course::factory()->create();
48|        $student = Student::factory()->create();
49|        CourseEnrollment::enroll($student, $course)->confirm();
50|
51|        return [$student, $course];
52|    }
53|
54|    // ── سند ────────────────────────────────────────────────
55|
56|    public function test_the_transcript_is_generated_without_the_panel_chrome(): void
57|    {
58|        $this->actingAsRole(Role::Admin);
59|        [$student, $course] = $this->enrolled();
60|
61|        Grade::record($student, $course, GradeType::Final, 'پایان‌ترم', 17);
62|
63|        $response = $this->get(route('students.transcript.print', $student));
64|
65|        $response->assertOk();
66|        // منو و سایهٔ پنل روی کاغذ نباید باشند
67|        $response->assertDontSee('drawer');
68|
69|        $response->assertSee('کارنامهٔ رسمی')
70|            ->assertSee($student->first_name)
71|            ->assertSee($course->title)
72|            ->assertSee('پایان‌ترم')
73|            ->assertSee('ریزنمرات')
74|            ->assertSee('امضای و تأیید مدیر آموزشگاه');
75|    }
76|
77|    public function test_a_passing_final_score_is_marked_as_accepted(): void
78|    {
79|        $this->actingAsRole(Role::Admin);
80|        [$student, $course] = $this->enrolled();
81|
82|        Grade::record($student, $course, GradeType::Homework, 'تکلیف اول', 18);
83|
84|        // وضعیت از روی کلاس سلول خوانده می‌شود، نه از متن: جمعِ پایین سند همیشه
85|        // «قبولی» و «مردود» را چاپ می‌کند، پس assertDontSee روی این کلمات دروغ می‌گوید
86|        $this->get(route('students.transcript.print', $student))
87|            ->assertOk()
88|            ->assertSee('class="center passed"', false)
89|            ->assertSee('قبولی');
90|    }
91|
92|    public function test_a_failing_final_score_is_marked_as_failed(): void
93|    {
94|        $this->actingAsRole(Role::Deputy);
95|        [$student, $course] = $this->enrolled();
96|
97|        // ۵ از ۲۰ یعنی ۲۵٪؛ میانگین وزنی همان ۵ را می‌دهد
98|        Grade::record($student, $course, GradeType::Midterm, 'میان‌ترم', 5);
99|
100|        $this->get(route('students.transcript.print', $student))
101|            ->assertOk()
102|            ->assertSee('class="center failed"', false)
103|            ->assertSee('مردود');
104|    }
105|
106|    public function test_a_student_without_any_grade_gets_a_document_marked_as_faqad_sabeghe(): void
107|    {
108|        $this->actingAsRole(Role::Admin);
109|        [$student] = $this->enrolled();
110|
111|        $response = $this->get(route('students.transcript.print', $student));
112|
113|        $response->assertOk();
114|        $response->assertSee('فاقد سابقه')
115|            ->assertSee($student->first_name);
116|        // سند باید امضا و شماره داشته باشد، حتی بدون نمره
117|        $response->assertSee('شماره سند')
118|            ->assertSee('امضای و تأیید مدیر آموزشگاه');
119|    }
120|
121|    public function test_a_student_with_no_enrollment_at_all_still_gets_a_document(): void
122|    {
123|        $this->actingAsRole(Role::Admin);
124|        $student = Student::factory()->create();
125|
126|        $this->get(route('students.transcript.print', $student))
127|            ->assertOk()
128|            ->assertSee('فاقد سابقه');
129|    }
130|
131|    public function test_the_pass_score_comes_from_settings_and_a_broken_value_is_ignored(): void
132|    {
133|        $transcript = new Transcript;
134|
135|        $this->assertSame(10.0, $transcript->passScore());
136|
137|        Setting::put(Transcript::PASS_SCORE, '12.5');
138|        $this->assertSame(12.5, $transcript->passScore());
139|
140|        // مقدار خارج از بازهٔ نمره نباید همه را مردود یا همه را قبول کند
141|        Setting::put(Transcript::PASS_SCORE, '900');
142|        $this->assertSame(Transcript::MAX_SCORE, $transcript->passScore());
143|
144|        Setting::put(Transcript::PASS_SCORE, 'یک‌مقدارخراب');
145|        $this->assertSame(10.0, $transcript->passScore());
146|    }
147|
148|    public function test_the_document_number_is_the_same_for_every_print_of_one_student(): void
149|    {
150|        $this->actingAsRole(Role::Admin);
151|        [$student] = $this->enrolled();
152|
153|        $first = $this->get(route('students.transcript.print', $student))->getContent();
154|        $second = $this->get(route('students.transcript.print', $student))->getContent();
155|
156|        $this->assertSame($first, $second);
157|    }
158|
159|    // ── دسترسی ────────────────────────────────────────────
160|
161|    public function test_finance_and_reception_cannot_open_the_transcript(): void
162|    {
163|        [$student] = $this->enrolled();
164|
165|        foreach ([Role::Finance, Role::Reception] as $role) {
166|            $this->actingAsRole($role);
167|
168|            $this->get(route('students.transcript.print', $student))->assertForbidden();
169|        }
170|    }
171|
172|    public function test_a_guest_is_sent_to_login(): void
173|    {
174|        [$student] = $this->enrolled();
175|
176|        $this->get(route('students.transcript.print', $student))
177|            ->assertRedirect(route('login'));
178|    }
