2|
3|namespace App\Services;
4|
5|use App\Enums\EnrollmentStatus;
6|use App\Enums\GradeType;
7|use App\Models\Course;
8|use App\Models\Grade;
9|use App\Models\Student;
10|use Illuminate\Support\Collection;
11|
12|/**
13| * میانگین وزنی و رتبه‌بندی.
14| *
15| * وزن روی «نوع نمره» است، نه روی تک‌تک نمره‌ها. میانگین سادهٔ همهٔ نمره‌ها یعنی
16| * بیست تکلیف می‌تواند پایان‌ترم را کاملاً بی‌اثر کند — یعنی کارنامهٔ دانش‌آموزی
17| * که همهٔ کلاس را کار کرده، از کسی که فقط امتحان داده ضعیف‌تر شود.
18| */
19|class WeightedAverage
20|{
21|    /**
22|     * نمرهٔ نهایی یک دانش‌آموز در یک دوره، از ۲۰.
23|     *
24|     * هر نوع نمره اول به درصد تبدیل و بعد با وزن همان نوع میانگین گرفته می‌شود.
25|     * وزن‌دادن به نمرهٔ خام اشتباه است: یک تکلیف ۱۰نمره‌ای و یک پایان‌ترم
26|     * ۲۰نمره‌ای اسمی ۲ برابر وزن دارند و ترم را به هم می‌ریزند.
27|     */
28|    public function finalScore(Student $student, Course $course): ?float
29|    {
30|        $weighted = $this->weightedPercentage($student, $course);
31|
32|        if ($weighted === null) {
33|            return null;
34|        }
35|
36|        return round($weighted * 20 / 100, 2);
37|    }
38|
39|    /** درصد وزنی، بدون تبدیل به ۲۰. */
40|    public function weightedPercentage(Student $student, Course $course): ?float
41|    {
42|        $byType = Grade::forStudentInCourse($student, $course)
43|            ->groupBy(fn (Grade $grade) => $grade->type->value);
44|
45|        $weightedSum = 0.0;
46|        $weightTotal = 0.0;
47|
48|        foreach ($byType as $typeValue => $grades) {
49|            $type = GradeType::tryFrom($typeValue);
50|
51|            if ($type === null || ! $type->countsTowardFinal()) {
52|                continue;
53|            }
54|
55|            $weight = $type->weight();
56|
57|            $weightedSum += $this->averagePercentage($grades) * $weight;
58|            $weightTotal += $weight;
59|        }
60|
61|        if ($weightTotal === 0.0) {
62|            return null;
63|        }
64|
65|        return round($weightedSum / $weightTotal, 2);
66|    }
67|
68|    /** میانگین سادهٔ درصدهای یک گروه نمره. */
69|    private function averagePercentage(Collection $grades): float
70|    {
71|        if ($grades->isEmpty()) {
72|            return 0.0;
73|        }
74|
75|        return $grades->sum(fn (Grade $grade) => $grade->percentage()) / $grades->count();
76|    }
77|
78|    /**
79|     * رتبهٔ دانش‌آموزان یک دوره، به ترتیب نمرهٔ نهایی.
80|     *
81|     * رتبه بدون تراز شدن یعنی دو نفر با نمرهٔ برابر رتبه‌های متفاوت می‌گیرند و
82|     * کارنامه‌شان با هم نمی‌خواند. مساوات با رتبهٔ یکسان برگردانده می‌شود
83|     * (rank-competition).
84|     *
85|     * @return Collection<int, array{student: Student, score: float|null, rank: int|null}>
86|     */
87|    public function rankStudents(Course $course): Collection
88|    {
89|        $rows = $course->enrollments()
90|            ->where('status', EnrollmentStatus::Confirmed->value)
91|            ->with('student')
92|            ->get()
93|            ->map(fn ($enrollment) => [
94|                'student' => $enrollment->student,
95|                'score' => $this->finalScore($enrollment->student, $course),
96|            ])
97|            ->sortByDesc('score')
98|            ->values();
99|
100|        $rank = 0;
101|        $index = 0;
102|        $previous = null;
103|
104|        return $rows->map(function (array $row) use (&$rank, &$index, &$previous) {
105|            $index++;
106|
107|            // دانش‌آموزی که هیچ نمره‌ای ندارد رتبه نمی‌گیرد؛ رتبهٔ صفر یا
