15| * آستانه‌ها یک تنظیم آموزشگاه‌اند، نه یک ثابت کد: اینجا مقدار پیش‌فرض است و
16| * بعداً از صفحهٔ تنظیمات می‌آید.
17| *
18| * «زیر آستانه» وقتی معنا دارد که درصد واقعاً قابل محاسبه باشد. اگر همهٔ
19| * جلسات موجه باشند درصد نداریم و نباید هشدار داد — دانش‌آموزی که جلسه نداشته
20| * غایب نیست.
21| */
22|class AttendanceThreshold
23|{
24|    public const WARNING_BELOW = 80.0;   // زیر این، هشدار جدی
25|
26|    public const CRITICAL_BELOW = 65.0; // زیر این، بیش از حد غیبت
27|
28|    public function __construct(
29|        private readonly ?float $warningBelow = null,
30|    ) {}
31|
32|    /**
33|     * آستانهٔ مؤثر: تنظیم آموزشگاه اگر هست، وگرنه پیش‌فرض کد.
34|     *
35|     * این مقدار به‌صورت lazy خوانده می‌شود تا ساختن سرویس در تست، نیاز به
36|     * تنظیمات نداشته باشد ولی در برنامه، تنظیم واقعی اعمال شود.
37|     */
38|    private function threshold(): float
39|    {
40|        return $this->warningBelow ?? Setting::attendanceWarning() ?? self::WARNING_BELOW;
41|    }
42|
43|    public function level(?float $rate): ?string
44|    {
45|        if ($rate === null) {
46|            return null;
47|        }
48|
49|        if ($rate < self::CRITICAL_BELOW) {
50|            return 'critical';
51|        }
52|
53|        return $rate < $this->threshold() ? 'warning' : 'ok';
54|    }
55|
56|    public function levelLabel(?float $rate): string
57|    {
58|        return match ($this->level($rate)) {
59|            'critical' => 'غیبت بیش از حد',
60|            'warning' => 'حضور زیر آستانه',
61|            'ok' => 'حضور مناسب',
62|            default => '—',
63|        };
64|    }
65|
66|    public function color(?float $rate): string
67|    {
68|        return match ($this->level($rate)) {
69|            'critical' => 'badge-error',
70|            'warning' => 'badge-warning',
71|            'ok' => 'badge-success',
72|            default => 'badge-ghost',
73|        };
74|    }
75|
76|    public function needsAttention(?float $rate): bool
77|    {
78|        return $this->level($rate) !== null && $this->level($rate) !== 'ok';
79|    }
80|
81|    /**
82|     * دانش‌آموزان یک دوره با درصد حضور و سطح هشدار.
