88|        return $course->enrollments()
89|            ->where('status', EnrollmentStatus::Confirmed->value)
90|            ->with('student')
91|            ->get()
92|            ->map(function ($enrollment) use ($course) {
93|                // یک بار محاسبه، دو بار استفاده: تکرار فراخوانی یعنی دو کوئری
