namespace App\Enums;

/**
 * وضعیت حضور و غیاب.
 *
 * «غیبت» و «موجه» دو چیز متفاوت‌اند: اولی جریمهٔ مالی دارد، دومی ندارد. اگر
 * این دو یکی شوند، خانواده‌ای که بیماری داشته جریمه می‌شود و کسی که نیامده
