     * ...
     */
    private function status(?float $score, ?float $rate, float $passScore): string
    {
        if ($score === null) {
            return 'pending';
        }

        if ($score < $passScore) {
            return 'failed';
        }

        // نمره کافی است ولی حضور زیر آستانهٔ آموزشگاه: قبولی مشروط.
